import re
import sys
from collections import defaultdict
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path = sys.argv[1] if len(sys.argv) > 1 else "budget.xlsx"
wb = load_workbook(path, data_only=True)
wbv = load_workbook(path, data_only=False)

def to_num(v):
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return v
    if isinstance(v, str):
        s = v.strip().replace(",", "").replace("$", "").replace("(", "-").replace(")", "")
        try:
            return float(s)
        except ValueError:
            return None
    return None

grand = 0.0
print(f"FILE: {path}")
print(f"SHEETS: {wb.sheetnames}")
print()

for ws, wsv in zip(wb.worksheets, wbv.worksheets):
    print(f"===== Sheet: {ws.title} =====")
    rows = [r for r in ws.iter_rows() if any(c.value is not None for c in r)]
    if not rows:
        print("(empty sheet)")
        print()
        continue

    for r in rows:
        for c in r:
            if c.value is not None:
                f = wsv[c.coordinate].value
                note = f"   [formula: {f}]" if isinstance(f, str) and f.startswith("=") else ""
                print(f"{c.coordinate}: {c.value!r}{note}")

    rowtexts = {}
    for r in rows:
        texts = [str(c.value) for c in r if isinstance(c.value, str)]
        rowtexts[r[0].row] = " ".join(texts)

    groups = defaultdict(list)
    for r in rows:
        for c in r:
            n = to_num(c.value)
            if n is not None:
                groups[c.column].append((c.row, c.value))

    best = None
    for col in sorted(groups):
        keep, tot = [], []
        for rownum, raw in groups[col]:
            if re.search(r"total", rowtexts.get(rownum, ""), re.I):
                tot.append(raw)
            else:
                keep.append(raw)
        vals = [to_num(v) for v in keep]
        col_sum = sum(v for v in vals if v is not None)
        label = get_column_letter(col)
        print(f"column {label}: non-total values={keep} sum={col_sum} total_row_values={tot}")
        if best is None or len(vals) > best[1]:
            best = (col_sum, len(vals), label)

    if best is not None:
        grand += best[0]
        print(f"candidate total for sheet '{ws.title}': {best[0]} (column {best[2]})")
    print()

print(f"GRAND TOTAL across all sheets: {grand}")

import sys, re
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path = sys.argv[1] if len(sys.argv) > 1 else "budget.xlsx"

def is_num(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)

def txt(v):
    return "" if v is None else str(v).strip()

MONEY = re.compile(r'^[$€£¥]?[ \t]*\d[\d,]*(\.\d+)?$')

def to_num(v):
    if is_num(v):
        return v
    if isinstance(v, str):
        s = v.strip()
        if MONEY.match(s):
            try:
                return float(s.lstrip('$€£¥ ').replace(',', ''))
            except ValueError:
                return None
    return None

HEAD = re.compile(r'expense|amount|cost|budget|actual|planned|spent|value|price|paid|forecast|total|category|item', re.I)
TOTAL = re.compile(r'\b(total|subtotal|grand total)\b', re.I)

wbv = load_workbook(path, data_only=True)
wbf = load_workbook(path, data_only=False)

print(f"FILE: {path}")
print("SHEETS:", wbv.sheetnames)

formulas = []
for ws in wbf.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if isinstance(c.value, str) and c.value.startswith("="):
                formulas.append(f"{ws.title}!{c.coordinate}")
print("FORMULA CELLS:", len(formulas), formulas[:20])

grand_candidates = []

for ws in wbv.worksheets:
    print("=" * 72)
    print(f"SHEET: {ws.title}  rows={ws.max_row} cols={ws.max_column} dims={ws.dimensions}")
    grid = [[c.value for c in r] for r in ws.iter_rows()]
    for ri, row in enumerate(grid, start=1):
        bits = [f"{get_column_letter(ci)}{ri}={v!r}" for ci, v in enumerate(row, start=1) if v is not None]
        if bits:
            print("  " + "  ".join(bits))

    ncols = max((len(r) for r in grid), default=0)
    for ci in range(ncols):
        data = []
        for ri in range(len(grid)):
            if ci < len(grid[ri]):
                v = to_num(grid[ri][ci])
                if v is not None:
                    data.append((ri, v))
        if not data:
            continue
        hdr = ""
        for ri in range(min(4, len(grid))):
            if ci < len(grid[ri]) and txt(grid[ri][ci]) and to_num(grid[ri][ci]) is None:
                hdr = txt(grid[ri][ci])
                break
        keep = []
        skipped_total = 0
        for ri, v in data:
            row_texts = [txt(x) for x in grid[ri][:ci] if txt(x)]
            if row_texts and TOTAL.search(" ".join(row_texts)):
                skipped_total += 1
            else:
                keep.append(v)
        flag = "  <== HEADER MATCH" if HEAD.search(hdr) else ""
        print(f"  [col {get_column_letter(ci + 1)} hdr={hdr!r}] numeric cells={len(data)} "
              f"sum incl total rows={sum(v for _, v in data):,.2f} | "
              f"sum excl total-labeled rows={sum(keep):,.2f} (total rows skipped: {skipped_total}){flag}")
        grand_candidates.append((ws.title, get_column_letter(ci + 1), hdr, sum(keep)))

print("=" * 72)
all_numbers = []
for ws in wbv.worksheets:
    for row in ws.iter_rows():
        for c in row:
            v = to_num(c.value)
            if v is not None:
                all_numbers.append(v)
print(f"GRAND TOTAL: sum of every numeric value in the file = {sum(all_numbers):,.2f} "
      f"(count={len(all_numbers)})")

